  'settings.shortcuts.resetAllConfirmTitle': 'รีเซ็ตปุ่มลัดทั้งหมด?',
  'settings.shortcuts.resetAllConfirmBody': 'ปุ่มลัดที่ผูกใหม่ทุกอันจะกลับไปเป็นค่าเริ่มต้น การกระทำนี้ยกเลิกไม่ได้',
