  'disk.title': 'โฟลเดอร์ปลายทาง',
  'disk.hint': 'พื้นที่ว่างและพื้นที่ที่ใช้ไปของทุกโฟลเดอร์ที่การดาวน์โหลดจะไปลงได้ พร้อมจำนวนที่คิวยังต้องเขียนลงในแต่ละโฟลเดอร์ ตัวเลขมาจากการเรียกอันเดียวกับที่ใช้ตรวจขีดจำกัดของดิสก์ และเก่าที่สุดแค่ไม่กี่วินาที พื้นที่ว่างบวกพื้นที่ที่ใช้ไปไม่ได้เท่ากับขนาดของดิสก์เสมอไป ระบบไฟล์กันส่วนหนึ่งไว้ให้ระบบ และโควตาต่อผู้ใช้ทำให้อินสแตนซ์นี้เหลือน้อยกว่าที่ดิสก์มีอยู่จริงได้ สองโฟลเดอร์ที่อยู่บนดิสก์เดียวกันจะแสดงดิสก์นั้นทั้งคู่ อย่าเอาแถวมาบวกกันเด็ดขาด',
  'disk.free': 'ว่าง',
  'disk.used': 'ใช้ไป',
  'disk.size': 'ขนาดของดิสก์',
  'disk.queued': 'ยังต้องเขียนอีก',
  'disk.queuedHint': 'สิ่งที่การดาวน์โหลดซึ่งยังค้างอยู่จะเพิ่มลงในโฟลเดอร์นี้ คือขนาดที่โฮสต์ประกาศไว้ ลบด้วยส่วนที่มาถึงแล้ว การดาวน์โหลดที่โฮสต์ไม่ยอมบอกขนาดจะนับเป็นศูนย์ตรงนี้ ตัวเลขนี้จึงเป็นค่าต่ำสุด ไม่ใช่คำสัญญา และนั่นคือเหตุที่โฟลเดอร์หนึ่งขึ้นศูนย์ไบต์ได้ ทั้งที่มีการดาวน์โหลดเรียงอยู่เป็นแถว การดาวน์โหลดที่คุณปิดไว้จะไม่ถูกนับ เป็นกฎเดียวกับตัวนับใต้รายการ การดาวน์โหลดที่กำลังทำงานอยู่แล้วมักถูกจองที่บนดิสก์ไปตั้งแต่วินาทีที่มันเริ่ม ไบต์ของมันจึงหายไปจากตัวเลขพื้นที่ว่างข้าง ๆ นี้แล้ว ไม่ได้มาซ้อนทับเพิ่มอีก',
  'disk.tasks': 'การดาวน์โหลด {n} รายการ',
