  'cookies.useStoredHint': 'สวิตช์ตัวเดียวสำหรับทั้งอินสแตนซ์ ไม่ใช่สำหรับลิงก์นี้ ถ้าปิดอยู่ ไฟล์ที่เก็บไว้จะไม่ถูกส่งไปไหนเลย และการวางอะไรลงที่นี่ก็ไม่เปลี่ยนอะไร มันเป็นส่วนหนึ่งของสิ่งที่ปุ่มบันทึกทำ ไม่ใช่การอ่านค่าปัจจุบันมาแสดง คุณจึงเห็นสิ่งที่หน้าต่างนี้กำลังจะทิ้งไว้ และที่เป็นสวิตช์แทนที่จะทำอัตโนมัติ ก็เพราะเซสชันที่เข้าสู่ระบบอยู่มีผลตามมา ขีดจำกัดหรือการแบนจะตกที่บัญชี ไม่ใช่ที่หมายเลขที่อยู่',
