  'settings.downloads.idleActionQuit': 'Quit KnightLoader',
  'settings.downloads.idleActionCommand': 'Run a command',
  'settings.downloads.idleActionSuspend': 'Send this machine to sleep',
  'settings.downloads.idleDeploymentContainer': 'This runs in a container. Its process is PID 1 inside its own namespace: quitting stops the container and nothing else, and it cannot put the machine underneath it to sleep, because that machine\'s power state is not something anything inside the container can reach. Whether the container comes back after a quit is decided by the restart policy you gave it, not by this setting. If you want the host asleep, use a command here that reaches the host.',
