  'settings.resolvers.toolsHint': 'yt-dlp reads the media page, ffmpeg joins the streams it hands back. Both are separate programs KnightLoader starts and neither is part of this build, so their versions are worth knowing: an out of date yt-dlp is the most common reason a media link that worked last month stops working.',
